head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[header > P > tooltip]<br/>GridView Header 영역으로 마우스가 들어왔을때 표시할 툴팁을 설정합니다.",
    "validation" : [
        "GridView Header 영역으로 마우스가 들어왔을때 표시할 툴팁을 설정합니다.",
        "툴팁으로 표시할 텍스트를 설정합니다.",
        "속성값은 참고용으로 사용되며 실제 툴팁은 Header Cell 값과 GridView 의 관련 속성을 설정해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_tooltip.setValue("Header 영역 툴팁");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정
    //  - tooltip 은 header(Header 영역) 단위 속성이며 dynamic N 이므로 렌더 시점에만 설정한다.
    //  - Header 툴팁이 실제로 표시되도록 GridView 에 tooltipHeader, tooltipHeaderShowAlways 를 고정 설정한다.
    let cTooltip = con_tooltip.getValue();
    let lblTooltip = (cTooltip === '') ? '미설정' : cTooltip;
    let attrTooltip = (cTooltip === '') ? '' : ' tooltip="' + cTooltip + '"';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] GridView 하위에 w2:header 를 선언하고 Header 영역에만 tooltip 속성을 설정. Header 툴팁 표시 조건으로 GridView 에 tooltipHeader=true, tooltipHeaderShowAlways=true 를 고정 설정하고 Header Cell 값은 name1 ~ name4 로 설정\n[현재] header tooltip = ' + lblTooltip + '\n[절차] 옵션 변경 후 Target 재생성 -> Header Cell 에 마우스 오버하여 툴팁을 띄운 뒤 그 상태에서 Header Cell 클릭\n[확인] 클릭 시 실제 표시된 툴팁 텍스트가 결과창에 출력됨. tooltip 반영 확인 버튼으로 선언한 tooltip 값이 렌더 결과에 반영되는지 확인"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (header 에 tooltip 설정)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" tooltipHeader="true" tooltipHeaderShowAlways="true" id="" style="width:600px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1"' + attrTooltip + '>';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="header_col1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="header_col2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="header_col3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="header_col4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 표시된 툴팁 텍스트 출력용 리스너 부착
    scwin.attachTooltipClick();
}



// 마우스 오버로 툴팁이 표시된 상태에서 클릭하면 실제 표시된 툴팁 텍스트를 출력한다.
// (capture 단계에서 읽어야 엔진이 툴팁을 닫기 전 값을 읽을 수 있음)
scwin.attachTooltipClick = function () {
    let gridElem = target1.render;
    if (!gridElem) {
        return;
    }

    if (scwin.tooltipClickFn && scwin.tooltipClickEl) {
        scwin.tooltipClickEl.removeEventListener("click", scwin.tooltipClickFn, true);
    }

    scwin.tooltipClickFn = function () {
        $c.gcm.getTooltipInfo(wf_body_bottom);
    };
    scwin.tooltipClickEl = gridElem;
    gridElem.addEventListener("click", scwin.tooltipClickFn, true);
}



// header 에 설정한 tooltip 의 실제 반영 여부 확인
scwin.btn_checkTooltip_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let cTooltip = con_tooltip.getValue();
    let structTooltip = (target1.struct && target1.struct.head && target1.struct.head.attr) ? target1.struct.head.attr.tooltip : undefined;
    let headArea = target1.render.querySelector("[id$='_head_table']");
    let headTh = headArea ? headArea.querySelector("tr > th") : null;

    let appliedCnt = 0;
    if (cTooltip !== '') {
        let elemList = target1.render.querySelectorAll("*");
        for (let i = 0; i < elemList.length; i++) {
            let elem = elemList[i];
            if (elem.getAttribute("tooltip") === cTooltip || elem.getAttribute("data-tooltip") === cTooltip || elem.getAttribute("title") === cTooltip || elem.getAttribute("aria-label") === cTooltip) {
                appliedCnt++;
            }
        }
    }

    bottom.setReturnValue("[1] header 에 설정한 tooltip : " + (cTooltip === '' ? '(미설정)' : cTooltip) + " / 선언값 보존 위치(struct.head.attr.tooltip) : " + (structTooltip == null ? '(없음)' : structTooltip));
    bottom.setReturnValue("[2] 렌더된 GridView 에서 선언값이 적용된 요소 개수(tooltip/data-tooltip/title/aria-label 기준) : " + (cTooltip === '' ? '-' : appliedCnt));
    bottom.setReturnValue("[3] Header 영역 요소의 data-tooltip 속성 : " + (headArea ? (headArea.getAttribute("data-tooltip") == null ? '(없음)' : headArea.getAttribute("data-tooltip")) : '(Header 영역 없음)') + " / Header Cell(th) 의 data-tooltip 속성 : " + (headTh ? (headTh.getAttribute("data-tooltip") == null ? '(없음)' : headTh.getAttribute("data-tooltip")) : '-'));
}
